import { type Result, ok, err } from '../result.ts';
import { searchNotes } from '../search.ts';
import { type NoteInput, parseNoteInput } from './json-body.ts';

export type Kind = 'create' | 'read';
export interface Handled { kind: Kind; result: Result<unknown> }
export interface Route { kind: Kind; needsBody: boolean; run: (store: NoteStore, arg: string) => Result<unknown> }

const create = (store: NoteStore, raw: string): Result<unknown> => {
  const input: Result<NoteInput> = parseNoteInput(raw);
  return input.ok ? store.add(input.value.title, input.value.body) : input;
};

const byId = (store: NoteStore, idText: string): Result<unknown> => {
  const id = /^\d+$/.test(idText) ? Number(idText) : NaN;
  return Number.isNaN(id) ? err('not found') : store.get(id);
};

const table: Record<string, Route> = {
  'POST /notes': { kind: 'create', needsBody: true, run: create },
  'GET /notes': { kind: 'read', needsBody: false, run: (s) => ok(s.list()) },
  'GET /search': { kind: 'read', needsBody: false, run: (s, q) => searchNotes(s.list(), q) },
  'GET /health': { kind: 'read', needsBody: false, run: () => ok({ status: 'ok' }) },
};

export function matchRoute(method: string, path: string): { route: Route; arg: string } | undefined {
  const exact = table[`${method} ${path}`];
  if (exact) return { route: exact, arg: '' };
  const m = method === 'GET' ? /^\/notes\/([^/]+)$/.exec(path) : null;
  return m ? { route: { kind: 'read', needsBody: false, run: byId }, arg: m[1] } : undefined;
}
