test('AC-15 p95 latency under 50ms per endpoint with 1000 notes', async () => {
  const store = new NoteStore();
  for (let i = 0; i < 1000; i++) store.add(`title ${i}`, `body ${i}`);
  const server = createNotesServer(store, () => {});
  await new Promise<void>((r) => server.listen(0, r));
  const url = `http://localhost:${(server.address() as AddressInfo).port}`;
  const endpoints: Array<[string, string, string?]> = [
    ['GET', '/health'], ['GET', '/notes'], ['GET', '/notes/500'], ['GET', '/search?q=title%2099'],
    ['POST', '/notes', JSON.stringify({ title: 'p', body: 'q' })],
  ];
  try {
    for (const [method, path, body] of endpoints) {
      const times: number[] = [];
      for (let i = 0; i < 200; i++) {
        const t = performance.now();
        const res = await fetch(`${url}${path}`, { method, body, headers: body ? { 'content-type': 'application/json' } : {} });
        await res.arrayBuffer();
        assert.ok(res.status < 400, `${method} ${path} -> ${res.status}`);
        times.push(performance.now() - t);
      }
      times.sort((a, b) => a - b);
      const p95 = times[Math.ceil(times.length * 0.95) - 1];
      assert.ok(p95 < 50, `${method} ${path} p95 ${p95.toFixed(1)}ms`);
    }
  } finally { await new Promise((r) => server.close(r)); }
});
