import assert from 'node:assert/strict';
import { spawn } from 'node:child_process';
import { createServer, type IncomingMessage, type ServerResponse } from 'node:http';
import type { AddressInfo } from 'node:net';

type Handler = (req: IncomingMessage, res: ServerResponse, body: string) => void;

async function runSmoke(handler: Handler | null) {
  const server = createServer((req, res) => {
    let body = '';
    req.on('data', (c) => (body += c));
    req.on('end', () => handler!(req, res, body));
  });
  let url = 'http://127.0.0.1:1';
  if (handler) {
    await new Promise<void>((r) => server.listen(0, r));
    url = `http://127.0.0.1:${(server.address() as AddressInfo).port}`;
  }
  try {
    return await new Promise<{ code: number | null; out: string }>((resolve) => {
      const p = spawn('node', ['scripts/smoke.ts'], { env: { ...process.env, SMOKE_URL: url } });
      let out = '';
      p.stdout.on('data', (d) => (out += d));
      p.stderr.on('data', (d) => (out += d));
      p.on('close', (code) => resolve({ code, out }));
    });
  } finally {
    if (handler) await new Promise((r) => server.close(r));
  }
}

const json = (res: ServerResponse, status: number, v: unknown) => {
  res.writeHead(status, { 'content-type': 'application/json' });
  res.end(JSON.stringify(v));
};

function healthy(overrides: Partial<Record<string, (res: ServerResponse) => void>> = {}): Handler {
  const notes: { id: number; title: string; body: string }[] = [];
  return (req, res, body) => {
    const key = req.url!.startsWith('/search') ? 'search' : req.url!.startsWith('/notes/') ? 'get' : req.url === '/notes' ? 'post' : 'health';
    if (overrides[key]) return overrides[key]!(res);
    if (key === 'health') return json(res, 200, { status: 'ok' });
    if (key === 'post') {
      const n = { id: notes.length + 1, ...JSON.parse(body) };
      notes.push(n);
      return json(res, 201, n);
    }
    if (key === 'get') return json(res, 200, notes[Number(req.url!.split('/')[2]) - 1]);
    return json(res, 200, notes);
  };
}

