import type { IncomingMessage } from 'node:http';
import { type Result, ok, err } from '../result.ts';

export interface NoteInput { title: string; body: string }

export function parseNoteInput(raw: string): Result<NoteInput> {
  let data: unknown;
  try {
    data = JSON.parse(raw);
  } catch {
    return err('invalid JSON');
  }
  if (typeof data !== 'object' || data === null) return err('invalid body');
  const { title, body } = data as Record<string, unknown>;
  if (typeof title !== 'string' || typeof body !== 'string') return err('title and body must be strings');
  return ok({ title, body });
}

export async function readBody(req: IncomingMessage): Promise<string> {
  const chunks: Buffer[] = [];
  for await (const c of req) chunks.push(c as Buffer);
  return Buffer.concat(chunks).toString('utf8');
}
