import { formatRequestLog } from './request-log.ts';

async function handle(store: NoteStore, req: IncomingMessage, res: ServerResponse): Promise<void> {
  const url = new URL(req.url ?? '/', 'http://localhost');
  const path = url.pathname;
  const hit = matchRoute(req.method ?? '', path);
  if (!hit) return send(res, notFound());
  const arg = hit.route.needsBody ? await readBody(req) : path === '/search' ? (url.searchParams.get('q') ?? '') : hit.arg;
  send(res, toReply(hit.route.kind, hit.route.run(store, arg)));
}

export function createNotesServer(store: NoteStore, log: (line: string) => void = console.log): Server {
  return createServer((req, res) => {
    const start = performance.now();
    const path = (req.url ?? '/').split('?')[0];
    res.once('finish', () => log(formatRequestLog(req.method ?? '', path, res.statusCode, performance.now() - start)));
    handle(store, req, res).catch(() => {
      if (!res.headersSent) send(res, badRequest());
    });
  });
}
