import type { Result } from '../result.ts';
import type { Kind } from './routes.ts';

export interface Reply { status: number; body: unknown }

export function toReply(kind: Kind, result: Result<unknown>): Reply {
  if (result.ok) return { status: kind === 'create' ? 201 : 200, body: result.value };
  return { status: result.error === 'not found' ? 404 : 400, body: { error: result.error } };
}

export function notFound(): Reply {
  return { status: 404, body: { error: 'not found' } };
}

export function send(res: ServerResponse, reply: Reply): void {
  res.writeHead(reply.status, { 'content-type': 'application/json' });
  res.end(JSON.stringify(reply.body));
}

export function badRequest(): Reply {
  return { status: 400, body: { error: 'bad request' } };
}

export function payloadTooLarge(): Reply {
  return { status: 413, body: { error: 'payload too large' } };
}

const ABORTED_STATUS = 499;

export function loggedStatus(res: ServerResponse): number {
  return res.writableFinished ? res.statusCode : ABORTED_STATUS;
}
